async function mcpCall(port, toolName, toolArgs) {
  const baseUrl = "http://72.62.255.251:" + port;

  // Step 1: Initialize and get session ID
  const initResp = await fetch(baseUrl + "/mcp", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Accept": "application/json" },
    body: JSON.stringify({
      jsonrpc: "2.0", id: 1, method: "initialize",
      params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "n8n-ron", version: "1.0" } }
    })
  });
  const sessionId = initResp.headers.get("mcp-session-id");

  // Step 2: Call tool
  const callResp = await fetch(baseUrl + "/mcp", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json",
      "Mcp-Session-Id": sessionId
    },
    body: JSON.stringify({
      jsonrpc: "2.0", id: 2, method: "tools/call",
      params: { name: toolName, arguments: toolArgs || {} }
    })
  });
  const result = await callResp.json();

  if (result.error) return "Error: " + result.error.message;
  if (result.result && result.result.content) {
    return result.result.content.map(c => c.text || JSON.stringify(c)).join("\n");
  }
  return JSON.stringify(result.result);
}

const input = $fromAI("tool_call", "JSON object with tool_name (string) and args (object)", "object");
const toolName = input.tool_name || input.toolName;
const args = input.args || input.arguments || {};
const result = await mcpCall(3100, toolName, args);
return result;

